AssistantMessageToolRequest(name='create', tool_call_id='tooluse_MCNTDqESNBaTVTWxDFXZgU', arguments={'file_text': "class ContactForm {
    constructor() {
        this.form = document.getElementById('contactForm');
        this.fields = {
            fullName: document.getElementById('fullName'),
            email: document.getElementById('email'),
            phone: document.getElementById('phone')
        };
        this.errors = {
            fullName: document.getElementById('fullNameError'),
            email: document.getElementById('emailError'),
            phone: document.getElementById('phoneError')
        };
        this.touched = new Set();
        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        // Track touched fields for validation display
        Object.values(this.fields).forEach(field => {
            field.addEventListener('blur', () => {
                this.touched.add(field.id);
                this.validateField(field);
            });
            field.addEventListener('input', () => {
                if (this.touched.has(field.id)) {
                    this.validateField(field);
                }
            });
        });
    }

    validateField(field) {
        const fieldName = field.name;
        const value = field.value.trim();
        const errorElement = this.errors[fieldName];
        let error = '';

        if (fieldName === 'fullName') {
            if (!value) {
                error = 'Full name is required';
            } else if (value.length < 2) {
                error = 'Full name must be at least 2 characters';
            }
        } else if (fieldName === 'email') {
            if (!value) {
                error = 'Email address is required';
            } else if (!this.isValidEmail(value)) {
                error = 'Please enter a valid email address';
            }
        } else if (fieldName === 'phone') {
            if (value && !this.isValidPhone(value)) {
                error = 'Please enter a valid phone number';
            }
        }

        if (error) {
            field.setAttribute('aria-invalid', 'true');
            field.setAttribute('aria-describedby', `${fieldName}Error`);
            errorElement.textContent = error;
        } else {
            field.setAttribute('aria-invalid', 'false');
            field.removeAttribute('aria-describedby');
            errorElement.textContent = '';
        }

        return !error;
    }

    validateForm() {
        let isValid = true;

        Object.values(this.fields).forEach(field => {
            this.touched.add(field.id);
            if (!this.validateField(field)) {
                isValid = false;
            }
        });

        return isValid;
    }

    isValidEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    isValidPhone(phone) {
        // Accepts various phone formats
        // +1 (555) 123-4567, 555-123-4567, (555) 123-4567, 555.123.4567, etc.
        const phoneRegex = /^[\+]?[(]?[0-9]{1,4}[)]?[-\s\.]?[(]?[0-9]{1,4}[)]?[-\s\.]?[0-9]{1,9}$/;
        return phoneRegex.test(phone.replace(/\s/g, ''));
    }

    handleSubmit(e) {
        e.preventDefault();

        if (this.validateForm()) {
            this.submitForm();
        }
    }

    submitForm() {
        const data = {
            fullName: this.fields.fullName.value.trim(),
            email: this.fields.email.value.trim(),
            phone: this.fields.phone.value.trim()
        };

        console.log('Form submitted:', data);
        alert(`Thank you for contacting us, ${data.fullName}!\n\nWe'll get back to you at ${data.email} as soon as possible.`);
        this.form.reset();
        this.touched.clear();
        Object.values(this.errors).forEach(error => error.textContent = '');
        Object.values(this.fields).forEach(field => {
            field.setAttribute('aria-invalid', 'false');
            field.removeAttribute('aria-describedby');
        });
    }
}

document.addEventListener('DOMContentLoaded', () => {
    new ContactForm();
});
